/**
 * AddMemberByEmailModal — Phase 4g.
 *
 * Two-step flow:
 *   1. Email type-ahead → lookupWorkspaceMemberByEmail
 *      - 200 → show resolved user, enable Add
 *      - 404 → show "user not found — invite them" with link to /admin/members
 *   2. Add → addWorkspaceMember(tenantID, { user_id, role })
 *
 * Closes on success; parent bumps reloadKey to refetch the table.
 */

import {
  useCallback,
  useEffect,
  useState,
  type FormEvent,
  type ReactElement,
} from "react";
import { z } from "zod";
import {
  emailSchema,
  fieldErrorsFromZod,
  useFieldErrors,
  type FieldErrors,
} from "@omnicore-platform/platform-chrome";

import { Modal } from "../components/Modal";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useLocale } from "@omnicore-platform/platform-chrome";
import {
  addWorkspaceMember,
  lookupWorkspaceMemberByEmail,
  type WorkspaceMemberLookup,
  type WorkspaceMemberRole,
} from "../api/tenants";

const lookupSchema = z.object({ email: emailSchema });

export interface AddMemberByEmailModalProps {
  open: boolean;
  tenantID: string;
  onClose: () => void;
  onAdded: () => void;
}

type LookupState =
  | { phase: "idle" }
  | { phase: "looking" }
  | { phase: "found"; user: WorkspaceMemberLookup }
  | { phase: "not_found"; email: string }
  | { phase: "error"; message: string };

type AddState =
  | { phase: "idle" }
  | { phase: "adding" }
  | { phase: "error"; message: string };

export function AddMemberByEmailModal({
  open,
  tenantID,
  onClose,
  onAdded,
}: AddMemberByEmailModalProps): ReactElement {
  useLocale();
  const [email, setEmail] = useState("");
  const [role, setRole] = useState<WorkspaceMemberRole>("member");
  const [lookup, setLookup] = useState<LookupState>({ phase: "idle" });
  const [add, setAdd] = useState<AddState>({ phase: "idle" });
  const { errors, setErrors, clear } = useFieldErrors();

  const lookupValid = lookupSchema.safeParse({ email: email.trim() }).success;

  function validateEmail(): void {
    const result = lookupSchema.safeParse({ email: email.trim() });
    if (!result.success) {
      const fieldErrors = fieldErrorsFromZod(result.error);
      if (fieldErrors.email !== undefined) {
        setErrors((prev: FieldErrors) => ({ ...prev, email: fieldErrors.email }));
      }
    } else {
      clear("email");
    }
  }

  useEffect(() => {
    if (!open) return;
    setEmail("");
    setRole("member");
    setLookup({ phase: "idle" });
    setAdd({ phase: "idle" });
    clear();
  }, [open, clear]);

  const handleLookup = useCallback(
    async (e: FormEvent<HTMLFormElement>): Promise<void> => {
      e.preventDefault();
      if (!email.trim()) return;
      setLookup({ phase: "looking" });
      setAdd({ phase: "idle" });
      try {
        const found = await lookupWorkspaceMemberByEmail(tenantID, email.trim());
        if (found) {
          setLookup({ phase: "found", user: found });
        } else {
          setLookup({ phase: "not_found", email: email.trim() });
        }
      } catch (err: unknown) {
        setLookup({
          phase: "error",
          message: err instanceof Error ? err.message : "Lookup failed",
        });
      }
    },
    [email, tenantID],
  );

  const handleAdd = useCallback(async (): Promise<void> => {
    if (lookup.phase !== "found") return;
    setAdd({ phase: "adding" });
    try {
      await addWorkspaceMember(tenantID, {
        user_id: lookup.user.user_id,
        role,
      });
      onAdded();
      onClose();
    } catch (err: unknown) {
      setAdd({
        phase: "error",
        message: err instanceof Error ? err.message : "Add failed",
      });
    }
  }, [lookup, role, tenantID, onAdded, onClose]);

  const footer = (
    <>
      <button
        type="button"
        onClick={onClose}
        className="
          inline-flex h-cog-6-5 items-center rounded-base border border-cog-divider
          bg-cog-surface px-cog-3 text-body-sm font-semibold text-cog-text-primary
          transition-colors duration-standard
          hover:border-cog-border hover:bg-cog-surface-muted
          focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1
        "
      >
        {m.workspaces_cancel_btn()}
      </button>
      <button
        type="button"
        onClick={handleAdd}
        disabled={lookup.phase !== "found" || add.phase === "adding"}
        data-testid="add-member-confirm"
        className="
          inline-flex h-cog-6-5 items-center rounded-base
          border border-cog-blue-600 bg-cog-blue-600 px-cog-3
          text-body-sm font-semibold text-white
          transition-colors duration-standard
          hover:border-cog-blue-700 hover:bg-cog-blue-700
          focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1
          disabled:cursor-not-allowed disabled:opacity-50
          dark:border-cog-blue-700 dark:bg-cog-blue-700 dark:text-white
        "
      >
        {add.phase === "adding" ? "Adding…" : "Add member"}
      </button>
    </>
  );

  return (
    <Modal
      title={m.admin_workspaces_add_member_title()}
      eyebrow={m.workspaces_assign_workspace_eyebrow()}
      open={open}
      onClose={onClose}
      footer={footer}
    >
      <form
        onSubmit={handleLookup}
        data-testid="add-member-form"
        className="flex flex-col gap-cog-4"
      >
        <div className="flex flex-col gap-cog-1">
          <p className="text-eyebrow uppercase tracking-cog-eyebrow font-bold text-cog-text-tertiary">
            {m.invite_email_label()}
          </p>
          <div className="flex flex-col gap-cog-1">
            <div className="flex gap-cog-2">
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                onBlur={validateEmail}
                aria-label={m.admin_workspaces_email_aria()}
                aria-invalid={Boolean(errors.email)}
                aria-describedby={errors.email ? "add-member-email-error" : undefined}
                data-testid="add-member-email"
                placeholder="user@example.com"
                className="
                  flex-1 rounded-base border border-cog-divider
                  bg-cog-surface px-cog-2 py-cog-2
                  text-body-sm text-cog-text-primary
                  focus:border-cog-blue-600 focus:outline-none
                "
              />
              <button
                type="submit"
                disabled={!lookupValid || lookup.phase === "looking"}
                data-testid="add-member-lookup"
              className="
                inline-flex h-cog-6-5 shrink-0 items-center rounded-base
                border border-cog-divider bg-cog-surface px-cog-3
                text-body-sm font-semibold text-cog-text-primary
                transition-colors duration-standard
                hover:border-cog-border hover:bg-cog-surface-muted
                focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1
                disabled:cursor-not-allowed disabled:opacity-50
              "
            >
              {lookup.phase === "looking" ? "Looking…" : "Find"}
            </button>
            </div>
            {errors.email && (
              <span
                id="add-member-email-error"
                role="alert"
                className="text-body-sm text-cog-danger-500"
              >
                {errors.email}
              </span>
            )}
          </div>
        </div>

        <div className="flex flex-col gap-cog-1">
          <p className="text-eyebrow uppercase tracking-cog-eyebrow font-bold text-cog-text-tertiary">
            {m.members_role_col()}
          </p>
          <select
            value={role}
            onChange={(e) => setRole(e.target.value as WorkspaceMemberRole)}
            aria-label={m.admin_workspaces_role_aria()}
            data-testid="add-member-role"
            className="
              rounded-base border border-cog-divider
              bg-cog-surface px-cog-2 py-cog-2
              text-body-sm text-cog-text-primary
              focus:border-cog-blue-600 focus:outline-none
            "
          >
            <option value="member">{m.roles_member_label()}</option>
            <option value="admin">{m.roles_admin_label()}</option>
            <option value="owner">{m.roles_owner_label()}</option>
          </select>
        </div>

        {lookup.phase === "found" && (
          <div
            data-testid="add-member-resolved"
            className="rounded-base border border-cog-divider bg-cog-surface-muted px-cog-3 py-cog-2 text-body-sm"
          >
            <p className="font-semibold text-cog-text-primary">
              {lookup.user.display_name || lookup.user.email}
            </p>
            <p className="text-cog-text-secondary">{lookup.user.email}</p>
          </div>
        )}

        {lookup.phase === "not_found" && (
          <p
            role="alert"
            data-testid="add-member-not-found"
            className="rounded-base border border-cog-divider bg-cog-surface-muted px-cog-3 py-cog-2 text-body-sm text-cog-text-secondary"
          >
            {m.invite_no_user_found_for()} <strong>{lookup.email}</strong>.{" "}
            <a
              href="/admin/members"
              className="font-semibold text-cog-blue-600 hover:underline dark:text-cog-blue-300"
            >
              {m.invite_them_first()}
            </a>
            {m.invite_then_add_them_here()}
          </p>
        )}

        {lookup.phase === "error" && (
          <p
            role="alert"
            data-testid="add-member-lookup-error"
            className="rounded-base border border-cog-danger-200 bg-cog-danger-50 px-cog-3 py-cog-2 text-body-sm text-cog-danger-600 dark:border-cog-danger-800 dark:bg-cog-danger-950 dark:text-cog-danger-dark"
          >
            {lookup.message}
          </p>
        )}

        {add.phase === "error" && (
          <p
            role="alert"
            data-testid="add-member-add-error"
            className="rounded-base border border-cog-danger-200 bg-cog-danger-50 px-cog-3 py-cog-2 text-body-sm text-cog-danger-600 dark:border-cog-danger-800 dark:bg-cog-danger-950 dark:text-cog-danger-dark"
          >
            {add.message}
          </p>
        )}
      </form>
    </Modal>
  );
}


