/**
 * WorkspaceSettingsTab — Phase 4g + 4h + 4i.
 *
 * Body of the Settings tab on the workspace detail route:
 *   - Display name + slug edit (name/slug)
 *   - Status dropdown (StatusControl) for ALL tenants — orgs AND
 *     workspaces. The earlier "child workspaces inherit, read-only"
 *     model conflicted with the soft-delete contract (DeleteTenantModal
 *     sets status → suspended on the tenant's own row, and the doc
 *     promises this is reversible). With the dropdown on workspaces,
 *     reactivating a soft-deleted workspace is a single click instead
 *     of an impossible operation. The server's transition matrix is
 *     authoritative; the dropdown just exposes admin-controllable
 *     targets.
 *   - Owner read-only
 *
 * The Danger Zone (Delete workspace button) was removed because
 * soft-delete is just a status transition to "suspended" — the
 * Status dropdown already exposes that, so having both surfaces
 * was redundant and confusing. The kebab menu on the main
 * /admin/tenants list still offers Delete for admins who want a
 * row-level action; the destructive flow itself
 * (DeleteTenantModal + server contract) is unchanged.
 *
 * Phase 4i: status is changed via the dropdown StatusControl. The
 * earlier inline Suspend/Restore buttons are gone — the dropdown
 * handles every admin-controllable transition (active ↔ suspended,
 * trial ↔ active/suspended, past_due → active).
 */

import {
  useCallback,
  useEffect,
  useState,
  type FormEvent,
  type ReactElement,
} from "react";

import {
  updateTenant,
  type AdminTenant,
} from "../api/tenants";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useLocale } from "@omnicore-platform/platform-chrome";
import { StatusControl } from "./StatusControl";
import { StudioAccessCard } from "./StudioAccessCard";
import { useSession } from "../lib/useSession";

export interface WorkspaceSettingsTabProps {
  tenant: AdminTenant;
  onUpdated: (next: AdminTenant) => void;
}

type SaveState =
  | { phase: "idle" }
  | { phase: "saving" }
  | { phase: "error"; message: string };

export function WorkspaceSettingsTab({
  tenant,
  onUpdated,
}: WorkspaceSettingsTabProps): ReactElement {
  useLocale();
  const sessionState = useSession();
  const [name, setName] = useState(tenant.name);
  const [slug, setSlug] = useState(tenant.slug);
  const [save, setSave] = useState<SaveState>({ phase: "idle" });
  const isOrg = !tenant.parent_id;

  // Derive the session tier for RBAC — default to "member" while loading so
  // the Studio Access card is not flash-rendered to non-admins.
  const sessionTier =
    sessionState.state === "ready" ? sessionState.session.tier : "member";

  useEffect(() => {
    setName(tenant.name);
    setSlug(tenant.slug);
    setSave({ phase: "idle" });
  }, [tenant.id, tenant.name, tenant.slug]);

  const nameDirty = name !== tenant.name;
  const slugDirty = slug !== tenant.slug;
  const dirty = nameDirty || slugDirty;
  const valid =
    (nameDirty ? name.trim().length > 0 : true) &&
    (slugDirty ? slug.trim().length > 0 : true);
  const canSave = dirty && valid && save.phase !== "saving";

  const handleSave = useCallback(
    async (e: FormEvent<HTMLFormElement>): Promise<void> => {
      e.preventDefault();
      if (!canSave) return;
      setSave({ phase: "saving" });
      try {
        const params: { name?: string; slug?: string } = {};
        if (nameDirty) params.name = name;
        if (slugDirty) params.slug = slug;
        const updated = await updateTenant(tenant.id, params);
        onUpdated(updated);
        setSave({ phase: "idle" });
      } catch (err: unknown) {
        setSave({
          phase: "error",
          message:
            err instanceof Error ? err.message : m.workspaces_settings_save_failed(),
        });
      }
    },
    [canSave, name, slug, nameDirty, slugDirty, tenant.id, onUpdated],
  );

  return (
    <section
      data-testid="workspace-settings-tab"
      className="flex flex-col gap-cog-5"
    >
      <form
        onSubmit={handleSave}
        data-testid="workspace-settings-form"
        className="flex flex-col gap-cog-4"
      >
        <Field
          label={m.tenants_display_name_label()}
          input={
            <input
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              aria-label={m.admin_common_display_name_aria()}
              data-testid="workspace-settings-name"
              className="
                w-full rounded-base border border-cog-divider
                bg-cog-surface px-cog-2 py-cog-2
                text-body-sm text-cog-text-primary
                focus:border-cog-blue-600 focus:outline-none
              "
            />
          }
        />

        <Field
          label={m.tenants_slug_label()}
          input={
            <input
              type="text"
              value={slug}
              onChange={(e) => setSlug(e.target.value)}
              aria-label={m.admin_common_slug_aria()}
              data-testid="workspace-settings-slug"
              className="
                w-full rounded-base border border-cog-divider
                bg-cog-surface px-cog-2 py-cog-2
                font-mono text-body-sm text-cog-text-primary
                focus:border-cog-blue-600 focus:outline-none
              "
            />
          }
          hint={m.workspaces_settings_slug_hint()}
        />

        <Field
          label={m.tenants_status_col_header()}
          input={<StatusControl tenant={tenant} onUpdated={onUpdated} />}
          hint={
            isOrg
              ? m.workspaces_settings_status_hint_org()
              : m.workspaces_settings_status_hint_workspace()
          }
        />

        {tenant.owner && (
          <Field
            label={m.tenants_owner_col_header()}
            input={
              <p className="text-body-sm text-cog-text-secondary">
                {tenant.owner.display_name ?? tenant.owner.email ?? tenant.owner.user_id}
              </p>
            }
          />
        )}

        {save.phase === "error" && (
          <p
            role="alert"
            data-testid="workspace-settings-error"
            className="rounded-base border border-cog-danger-200 bg-cog-danger-50 px-cog-3 py-cog-2 text-body-sm text-cog-danger-600 dark:border-cog-danger-800 dark:bg-cog-danger-950 dark:text-cog-danger-dark"
          >
            {save.message}
          </p>
        )}

        <div>
          <button
            type="submit"
            disabled={!canSave}
            data-testid="workspace-settings-save"
            className="
              inline-flex h-cog-6-5 items-center rounded-base
              border border-cog-blue-600 bg-cog-blue-600 px-cog-3
              text-body-sm font-semibold text-white
              transition-colors duration-standard
              hover:border-cog-blue-700 hover:bg-cog-blue-700
              focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1
              disabled:cursor-not-allowed disabled:opacity-50
              dark:border-cog-blue-700 dark:bg-cog-blue-700 dark:text-white
            "
          >
            {save.phase === "saving"
              ? m.workspaces_saving()
              : m.workspaces_settings_save()}
          </button>
        </div>
      </form>

      {/* Studio Access card — org-level only (not child workspaces) */}
      {isOrg && (
        <StudioAccessCard
          tenant={tenant}
          onUpdated={onUpdated}
          tier={sessionTier}
        />
      )}
    </section>
  );
}

function Field({
  label,
  input,
  hint,
}: {
  label: string;
  input: ReactElement;
  hint?: string;
}): ReactElement {
  return (
    <div className="flex flex-col gap-cog-1">
      <p className="text-eyebrow uppercase tracking-cog-eyebrow font-bold text-cog-text-tertiary">
        {label}
      </p>
      {input}
      {hint && <p className="text-micro text-cog-text-tertiary">{hint}</p>}
    </div>
  );
}



