/**
 * AddMemberByEmailModal — Phase 4g.
 *
 * Two-step flow:
 *   1. Email type-ahead → lookupWorkspaceMemberByEmail
 *      - 200 → show resolved user, enable Add
 *      - 404 → show "user not found — invite them" with link to /admin/members
 *   2. Add → addWorkspaceMember(tenantID, { user_id, role })
 *
 * Closes on success; parent bumps reloadKey to refetch the table.
 */

import {
  useCallback,
  useEffect,
  useState,
  type FormEvent,
  type ReactElement,
} from "react";
import { z } from "zod";
import {
  emailSchema,
  fieldErrorsFromZod,
  useFieldErrors,
  type FieldErrors,
} from "@omnicore-platform/platform-chrome";

import { Modal } from "../components/Modal";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useLocale } from "@omnicore-platform/platform-chrome";
import {
  addWorkspaceMember,
  lookupWorkspaceMemberByEmail,
  type WorkspaceMemberLookup,
  type WorkspaceMemberRole,
} from "../api/tenants";

const lookupSchema = z.object({ email: emailSchema });

export interface AddMemberByEmailModalProps {
  open: boolean;
  tenantID: string;
  onClose: () => void;
  onAdded: () => void;
}

type LookupState =
  | { phase: "idle" }
  | { phase: "looking" }
  | { phase: "found"; user: WorkspaceMemberLookup }
  | { phase: "not_found"; email: string }
  | { phase: "error"; message: string };

type AddState =
  | { phase: "idle" }
  | { phase: "adding" }
  | { phase: "error"; message: string };

export function AddMemberByEmailModal({
  open,
  tenantID,
  onClose,
  onAdded,
}: AddMemberByEmailModalProps): ReactElement {
  useLocale();
  const [email, setEmail] = useState("");
  const [role, setRole] = useState<WorkspaceMemberRole>("member");
  const [lookup, setLookup] = useState<LookupState>({ phase: "idle" });
  const [add, setAdd] = useState<AddState>({ phase: "idle" });
  const { errors, setErrors, clear } = useFieldErrors();

  const lookupValid = lookupSchema.safeParse({ email: email.trim() }).success;

  function validateEmail(): void {
    const result = lookupSchema.safeParse({ email: email.trim() });
    if (!result.success) {
      const fieldErrors = fieldErrorsFromZod(result.error);
      if (fieldErrors.email !== undefined) {
        setErrors((prev: FieldErrors) => ({ ...prev, email: fieldErrors.email }));
      }
    } else {
      clear("email");
    }
  }

  useEffect(() => {
    if (!open) return;
    setEmail("");
    setRole("member");
    setLookup({ phase: "idle" });
    setAdd({ phase: "idle" });
    clear();
  }, [open, clear]);

  const handleLookup = useCallback(
    async (e: FormEvent<HTMLFormElement>): Promise<void> => {
      e.preventDefault();
      if (!email.trim()) return;
      setLookup({ phase: "looking" });
      setAdd({ phase: "idle" });
      try {
        const found = await lookupWorkspaceMemberByEmail(tenantID, email.trim());
        if (found) {
          setLookup({ phase: "found", user: found });
        } else {
          setLookup({ phase: "not_found", email: email.trim() });
        }
      } catch (err: unknown) {
        setLookup({
          phase: "error",
          message: err instanceof Error ? err.message : "Lookup failed",
        });
      }
    },
    [email, tenantID],
  );

  const handleAdd = useCallback(async (): Promise<void> => {
    if (lookup.phase !== "found") return;
    setAdd({ phase: "adding" });
    try {
      await addWorkspaceMember(tenantID, {
        user_id: lookup.user.user_id,
        role,
      });
      onAdded();
      onClose();
    } catch (err: unknown) {
      setAdd({
        phase: "error",
        message: err instanceof Error ? err.message : "Add failed",
      });
    }
  }, [lookup, role, tenantID, onAdded, onClose]);

  const footer = (
    <>
      <button
        type="button"
        onClick={onClose}
        className="
          inline-flex h-cog-6-5 items-center rounded-base border border-cog-divider
          bg-cog-surface px-cog-3 text-body-sm font-semibold text-cog-text-primary
          transition-colors duration-standard
          hover:border-cog-border hover:bg-cog-surface-muted
          focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1
        "
      >
        {m.workspaces_cancel_btn()}
      </button>
      <button
        type="button"
        onClick={handleAdd}
        disabled={lookup.phase !== "found" || add.phase === "adding"}
        data-testid="add-member-confirm"
        className="
          inline-flex h-cog-6-5 items-center rounded-base
          border border-cog-blue-600 bg-cog-blue-600 px-cog-3
          text-body-sm font-semibold text-white
          transition-colors duration-standard
