/**
 * AssignUserModal — Phase 4k.
 *
 * Type-ahead search across the org's full user list (loaded once on open).
 * Client-side filter by display_name or email substring. Selecting a user
 * shows a resolved card; submitting calls addWorkspaceMember.
 */

import {
  useCallback,
  useEffect,
  useState,
  type ReactElement,
} from "react";
import { z } from "zod";
import { uuidSchema } from "@omnicore-platform/platform-chrome";

import { Modal } from "../components/Modal";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useLocale } from "@omnicore-platform/platform-chrome";
import {
  addWorkspaceMember,
  listOrgMembers,
  type OrgMemberCandidate,
  type WorkspaceMemberRole,
} from "../api/tenants";
import { listUsers } from "../api/users";

const assignSchema = z.object({
  user_id: uuidSchema,
  role: z.enum(["member", "admin", "owner", "viewer"]),
});

export interface AssignUserModalProps {
  open: boolean;
  tenantID: string;
  /** When set, the assignable user list is scoped to this organization's
   *  invited members (the workspace's parent org) instead of the admin's
   *  active-org users. Absent → fall back to the active-org user list. */
  parentOrgId?: string;
  /** Determines which role options the role <select> offers.
   *  "org" → Owner, Admin, Member, Viewer (4).
   *  "workspace" → Admin, Member, Viewer (3); a workspace assignment never
   *  grants Owner. Defaults to "workspace" — the original surface assigns
   *  members to a workspace. */
  roleScope?: "org" | "workspace";
  onClose: () => void;
  onAdded: () => void;
}

/** The role option set per scope, in display order. The "value" feeds the
 *  membership write (and is the wire role); the "label" is rendered via the
 *  roles i18n catalog. Owner is intentionally absent from "workspace". */
const ROLE_OPTIONS: Record<
  NonNullable<AssignUserModalProps["roleScope"]>,
  readonly { readonly value: WorkspaceMemberRole; readonly label: () => string }[]
> = {
  org: [
    { value: "owner", label: m.roles_owner_label },
    { value: "admin", label: m.roles_admin_label },
    { value: "member", label: m.roles_member_label },
    { value: "viewer", label: m.roles_viewer_label },
  ],
  workspace: [
    { value: "admin", label: m.roles_admin_label },
    { value: "member", label: m.roles_member_label },
    { value: "viewer", label: m.roles_viewer_label },
  ],
};

/** Minimal shape the list/select/submit logic needs, common to both
 *  sources (active-org users and parent-org members). The submit depends
 *  only on keycloak_user_id; the list renders display_name + email. */
type AssignCandidate = OrgMemberCandidate;

type UsersState =
  | { phase: "loading" }
  | { phase: "loaded"; users: AssignCandidate[] }
  | { phase: "error"; message: string };

type AddState =
  | { phase: "idle" }
  | { phase: "adding" }
  | { phase: "error"; message: string };

export function AssignUserModal({
  open,
  tenantID,
  parentOrgId,
  roleScope = "workspace",
  onClose,
  onAdded,
}: AssignUserModalProps): ReactElement {
  useLocale();
  const roleOptions = ROLE_OPTIONS[roleScope];
  const [query, setQuery] = useState("");
  const [usersState, setUsersState] = useState<UsersState>({ phase: "loading" });
  const [selected, setSelected] = useState<AssignCandidate | null>(null);
  const [role, setRole] = useState<WorkspaceMemberRole>("member");
  const [addState, setAddState] = useState<AddState>({ phase: "idle" });

  // Reset and load the assignable user list each time the modal opens.
  // When a parentOrgId is given, scope the list to that organization's
  // invited members (the workspace's parent org). Otherwise fall back to
  // the admin's active-org user list.
  useEffect(() => {
    if (!open) return;
    setQuery("");
    setSelected(null);
    setRole("member");
    setAddState({ phase: "idle" });
    setUsersState({ phase: "loading" });

    let cancelled = false;
    const load: Promise<AssignCandidate[]> = parentOrgId
      ? listOrgMembers(parentOrgId).then((result) => result.users)
      : listUsers().then((result) =>
          result.users.map((u) => ({
            keycloak_user_id: u.keycloak_user_id,
            email: u.email,
            display_name: u.display_name,
          })),
        );
    load
      .then((users) => {
        if (cancelled) return;
        setUsersState({ phase: "loaded", users });
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setUsersState({
          phase: "error",
          message: err instanceof Error ? err.message : "Failed to load users",
        });
      });

    return () => {
      cancelled = true;
    };
  }, [open, parentOrgId]);

  const handleSubmit = useCallback(async (): Promise<void> => {
    if (!selected) return;
    setAddState({ phase: "adding" });
    try {
      // org.memberships.user_id stores the Keycloak sub UUID — never the
      // identity-svc UUIDv7 (selected.id). The workspace switcher resolves
      // memberships against claims.Subject = Keycloak sub; submitting the
      // wrong identifier silently makes the membership invisible to its
      // own user. Mirrors the convention pinned by
      // TestInvite_StoresKeycloakUserIDInMembership in admin-bff.
      await addWorkspaceMember(tenantID, {
        user_id: selected.keycloak_user_id,
        role,
      });
      onAdded();
      onClose();
    } catch (err: unknown) {
      setAddState({
        phase: "error",
        message: err instanceof Error ? err.message : "Add failed",
      });
    }
  }, [selected, tenantID, role, onAdded, onClose]);

  const filtered: AssignCandidate[] =
    usersState.phase === "loaded"
      ? (() => {
          const q = query.trim().toLowerCase();
          if (q === "") return usersState.users;
          return usersState.users.filter(
            (u) =>
              u.display_name.toLowerCase().includes(q) ||
              u.email.toLowerCase().includes(q),
          );
        })()
      : [];

  const footer = (
    <>
      <button
        type="button"
        onClick={onClose}
        className="
          inline-flex h-cog-6-5 items-center rounded-base border border-cog-divider
          bg-cog-surface px-cog-3 text-body-sm font-semibold text-cog-text-primary
          transition-colors duration-standard
          hover:border-cog-border hover:bg-cog-surface-muted
          focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1
        "
      >
        {m.workspaces_cancel_btn()}
      </button>
      <button
        type="button"
        onClick={() => void handleSubmit()}
        disabled={
          !assignSchema.safeParse({
            user_id: selected?.keycloak_user_id ?? "",
            role,
          }).success ||
          addState.phase === "adding"
        }
        data-testid="assign-user-submit"
        className="
          inline-flex h-cog-6-5 items-center rounded-base
          border border-cog-blue-600 bg-cog-blue-600 px-cog-3
          text-body-sm font-semibold text-white
          transition-colors duration-standard
          hover:border-cog-blue-700 hover:bg-cog-blue-700
          focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1
          disabled:cursor-not-allowed disabled:opacity-50
          dark:border-cog-blue-700 dark:bg-cog-blue-700 dark:text-white
        "
      >
        {addState.phase === "adding" ? "Assigning…" : "Assign"}
      </button>
    </>
  );

  return (
    <Modal
      title={m.admin_workspaces_assign_user_title()}
      eyebrow={m.workspaces_assign_workspace_eyebrow()}
      open={open}
      onClose={onClose}
      footer={footer}
    >
      <div className="flex flex-col gap-cog-4">
        {/* Search input — always shown; hidden if a user is already resolved */}
        {selected === null && (
          <div className="flex flex-col gap-cog-1">
            <label
              htmlFor="assign-user-search-input"
              className="text-eyebrow uppercase tracking-cog-eyebrow font-bold text-cog-text-tertiary"
            >
              {m.workspaces_search_by_name_or_email()}
            </label>
            <input
              id="assign-user-search-input"
              type="text"
              // eslint-disable-next-line jsx-a11y/no-autofocus -- Radix dialog already traps focus; this only moves it from the close button to the search field.
              autoFocus
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              data-testid="assign-user-search"
              placeholder="e.g. Alice or alice@acme.test"
              className="
                rounded-base border border-cog-divider
                bg-cog-surface px-cog-2 py-cog-2
                text-body-sm text-cog-text-primary
                focus:border-cog-blue-600 focus:outline-none
              "
            />
          </div>
        )}

        {/* Loading / error states for user list */}
        {usersState.phase === "loading" && selected === null && (
          <p className="text-body-sm text-cog-text-tertiary">{m.workspaces_loading_users()}</p>
        )}

        {usersState.phase === "error" && selected === null && (
          <p
            role="alert"
            className="rounded-base border border-cog-danger-200 bg-cog-danger-50 px-cog-3 py-cog-2 text-body-sm text-cog-danger-600 dark:border-cog-danger-800 dark:bg-cog-danger-950 dark:text-cog-danger-dark"
          >
            {usersState.message}
          </p>
        )}

        {/* Filtered user list */}
        {usersState.phase === "loaded" && selected === null && (
          <ul className="max-h-cog-17 overflow-y-auto rounded-base border border-cog-divider bg-cog-surface">
            {filtered.map((u) => (
              <li key={u.keycloak_user_id}>
                <button
                  type="button"
                  data-testid={`assign-user-result-${u.keycloak_user_id}`}
                  onClick={() => setSelected(u)}
                  className="
                    w-full px-cog-3 py-cog-2 text-left text-body-sm
                    hover:bg-cog-surface-muted
                    focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-cog-focus
                  "
                >
                  <p className="font-semibold text-cog-text-primary">
                    {u.display_name || u.email}
                  </p>
                  <p className="text-micro text-cog-text-tertiary">{u.email}</p>
                </button>
              </li>
            ))}
          </ul>
        )}

        {/* Resolved card shown after selection */}
        {selected !== null && (
          <div
            data-testid="assign-user-resolved"
            className="flex items-center justify-between rounded-base border border-cog-divider bg-cog-surface-muted px-cog-3 py-cog-2 text-body-sm"
          >
            <div>
              <p className="font-semibold text-cog-text-primary">
                {selected.display_name || selected.email}
              </p>
              <p className="text-cog-text-secondary">{selected.email}</p>
            </div>
            <button
              type="button"
              onClick={() => setSelected(null)}
              className="
                text-body-sm font-semibold text-cog-blue-600
                hover:underline
                focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1
                dark:text-cog-blue-300
              "
            >
              {m.workspaces_change_btn()}
            </button>
          </div>
        )}

        {/* Role select */}
        <div className="flex flex-col gap-cog-1">
          <p className="text-eyebrow uppercase tracking-cog-eyebrow font-bold text-cog-text-tertiary">
            {m.members_role_col()}
          </p>
          <select
            value={role}
            onChange={(e) => setRole(e.target.value as WorkspaceMemberRole)}
            aria-label={m.admin_workspaces_role_aria()}
            data-testid="assign-user-role"
            className="
              rounded-base border border-cog-divider
              bg-cog-surface px-cog-2 py-cog-2
              text-body-sm text-cog-text-primary
              focus:border-cog-blue-600 focus:outline-none
            "
          >
            {roleOptions.map((opt) => (
              <option key={opt.value} value={opt.value}>
                {opt.label()}
              </option>
            ))}
          </select>
        </div>

        {/* Add error */}
        {addState.phase === "error" && (
          <p
            role="alert"
            data-testid="assign-user-add-error"
            className="rounded-base border border-cog-danger-200 bg-cog-danger-50 px-cog-3 py-cog-2 text-body-sm text-cog-danger-600 dark:border-cog-danger-800 dark:bg-cog-danger-950 dark:text-cog-danger-dark"
          >
            {addState.message}
          </p>
        )}
      </div>
    </Modal>
  );
}


