/**
 * OrgWorkspacesTab — Phase 4h.
 *
 * 4th tab on the workspace detail page, rendered only when the current
 * tenant has no parent (i.e. it's an organization). Lists every
 * workspace owned by this org with add / edit / delete affordances.
 *
 * Workspace creation pre-fills parent_id so admins can't accidentally
 * mount a child under a different org. Delete + edit reuse the table
 * row kebab from the main list for consistency.
 */

import {
  useCallback,
  useEffect,
  useState,
  type ReactElement,
} from "react";
import { useNavigate } from "react-router-dom";

import {
  listTenants,
  type AdminTenant,
} from "../api/tenants";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useLocale } from "@omnicore-platform/platform-chrome";
import { TenantRowMenu } from "../tenants/TenantRowMenu";
import { tenantStatusPillFor } from "../tenants/TenantStatusPill";
import { CreateTenantModal } from "../tenants/CreateTenantModal";
import { EditTenantModal } from "../tenants/EditTenantModal";
import { DeleteTenantModal } from "../tenants/DeleteTenantModal";

export interface OrgWorkspacesTabProps {
  /** The org tenant whose children this tab lists. */
  org: AdminTenant;
}

type LoadState =
  | { phase: "loading" }
  | { phase: "loaded"; children: AdminTenant[] }
  | { phase: "error"; message: string };

export function OrgWorkspacesTab({ org }: OrgWorkspacesTabProps): ReactElement {
  useLocale();
  const navigate = useNavigate();
  const [state, setState] = useState<LoadState>({ phase: "loading" });
  const [reloadKey, setReloadKey] = useState(0);
  const [createOpen, setCreateOpen] = useState(false);
  const [editTarget, setEditTarget] = useState<AdminTenant | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<AdminTenant | null>(null);

  useEffect(() => {
    let cancelled = false;
    setState({ phase: "loading" });
    listTenants({ parent_id: org.id, page_size: 200 })
      .then((res) => {
        if (cancelled) return;
        const sorted = [...res.tenants].sort((a, b) =>
          a.name.localeCompare(b.name, undefined, { sensitivity: "base" }),
        );
        setState({ phase: "loaded", children: sorted });
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setState({
          phase: "error",
          message: err instanceof Error ? err.message : "Failed to load workspaces",
        });
      });
    return () => {
      cancelled = true;
    };
  }, [org.id, reloadKey]);

  const handleCreated = useCallback(() => {
    setCreateOpen(false);
    setReloadKey((k) => k + 1);
  }, []);

  const handleEdited = useCallback(() => {
    setEditTarget(null);
    setReloadKey((k) => k + 1);
  }, []);

  const handleDeleted = useCallback(() => {
    setDeleteTarget(null);
    setReloadKey((k) => k + 1);
  }, []);

  return (
    <section
      data-testid="org-workspaces-tab"
      className="flex flex-col gap-cog-3"
    >
      <div className="flex items-center justify-between">
        <h2 className="text-body-base font-semibold text-cog-text-primary">
          {m.workspaces_in_prefix()} {org.name}
        </h2>
        <button
          type="button"
          onClick={() => setCreateOpen(true)}
          data-testid="org-workspaces-add"
          className="
            inline-flex h-cog-6-5 items-center rounded-base
            border border-cog-blue-600 bg-cog-blue-600 px-cog-3
            text-body-sm font-semibold text-white
            transition-colors duration-standard
            hover:border-cog-blue-700 hover:bg-cog-blue-700
            focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1
            dark:border-cog-blue-700 dark:bg-cog-blue-700 dark:text-white
          "
        >
          {m.workspaces_add_workspace_btn()}
        </button>
      </div>

      {state.phase === "loading" && (
        <p className="text-body-sm text-cog-text-secondary">{m.workspaces_loading_workspaces()}</p>
      )}

      {state.phase === "error" && (
        <p
          role="alert"
          data-testid="org-workspaces-error"
          className="rounded-base border border-cog-danger-200 bg-cog-danger-50 px-cog-3 py-cog-2 text-body-sm text-cog-danger-600 dark:border-cog-danger-800 dark:bg-cog-danger-950 dark:text-cog-danger-dark"
        >
          {state.message}
        </p>
      )}

      {state.phase === "loaded" && state.children.length === 0 && (
        <p
          data-testid="org-workspaces-empty"
          className="text-body-sm text-cog-text-secondary"
        >
          {m.workspaces_no_workspaces_add_first()}
        </p>
      )}

      {state.phase === "loaded" && state.children.length > 0 && (
        <div
          data-testid="org-workspaces-table"
          className="overflow-hidden rounded-base border border-cog-divider bg-cog-surface"
        >
          <table className="w-full text-body-sm">
            <thead className="bg-cog-surface-muted text-cog-text-secondary">
              <tr>
                <th className="px-cog-3 py-cog-2 text-left font-semibold">{m.tenants_workspace_col_header()}</th>
                <th className="px-cog-3 py-cog-2 text-left font-semibold">{m.tenants_slug_label()}</th>
                {/* Workspaces now carry their own status (active vs
                    suspended via the soft-delete-reversal path). Show
                    it so soft-deleted workspaces are visible at a
                    glance and admins can navigate in to restore them. */}
                <th className="px-cog-3 py-cog-2 text-left font-semibold">{m.tenants_status_col_header()}</th>
                <th className="px-cog-3 py-cog-2 text-right font-semibold sr-only">
                  {m.tenants_actions_col_header()}
                </th>
