                  className="cursor-pointer transition-colors duration-standard hover:bg-cog-surface-muted focus-visible:bg-cog-surface-muted focus-visible:outline-none"
                >
                  <td className="px-cog-3 py-cog-2 font-semibold text-cog-text-primary">
                    {c.name}
