/**
 * StatusControl — Phase 4i.
 *
 * Status dropdown with trial-duration sub-picker. Renders for BOTH
 * organizations and workspaces (workspaces use it to reverse the
 * soft-delete-by-suspend flow from DeleteTenantModal).
 *
 * Transition matrix (enforced server-side; this component just filters
 * the dropdown to admin-controllable targets):
 *
 *   Active     → Active, Suspended
 *   Trial      → Active, Trial, Suspended
 *   Past Due   → Active, Past Due
 *   Suspended  → Active, Trial, Suspended
 *
 * Workspaces have one additional restriction: Trial is hidden from
 * their dropdown entirely. Trial is a billing concept that lives at
 * the org level — workspaces enter Trial only via cascade from the
 * parent org, never via direct admin action. The org-svc enforces
 * this on the wire (4xx if a workspace is targeted at Trial); the
 * dropdown filter is a UX layer so the admin never sees an option
 * they can't actually pick.
 *
 * Past Due never appears as a *selectable* option — it's only the
 * label shown when current status is already Past Due. Reaching
 * Past Due is the billing-automation path's job.
 */

import {
  useCallback,
  useState,
  type ReactElement,
} from "react";

import {
  updateTenantStatus,
  type AdminTenant,
  type SettableTenantStatus,
  type TenantStatus,
} from "../api/tenants";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useLocale } from "@omnicore-platform/platform-chrome";
import { TenantStatusPill } from "../tenants/TenantStatusPill";

export interface StatusControlProps {
  tenant: AdminTenant;
  onUpdated: (next: AdminTenant) => void;
}

type Phase =
  | { kind: "idle" }
  | { kind: "picking_trial"; days: number }
  | { kind: "saving" }
  | { kind: "error"; message: string };

const TRIAL_PRESETS: readonly { label: string; days: number }[] = [
  { label: "30 days", days: 30 },
  { label: "90 days", days: 90 },
  { label: "180 days", days: 180 },
];

/** allowedTargets returns the dropdown options for a given current
 *  status. The current status is always included as a self-option so
 *  the select reads as "current value" without surprises.
 *
 *  When `isWorkspace` is true (the tenant has a parent_id), Trial is
 *  filtered out — see the file-level comment for the rationale. */
function allowedTargets(
  current: TenantStatus,
  isWorkspace: boolean,
): SettableTenantStatus[] {
  const all: SettableTenantStatus[] = (() => {
    switch (current) {
      case "active":
        return ["active", "suspended"];
      case "trial":
        return ["active", "trial", "suspended"];
      case "past_due":
        return ["active"];
      case "suspended":
        return ["active", "trial", "suspended"];
      default:
        return ["active"];
    }
  })();
  return isWorkspace ? all.filter((t) => t !== "trial") : all;
}

function labelFor(s: SettableTenantStatus | "past_due"): string {
  switch (s) {
    case "active":
      return m.tenants_tenant_status_active();
    case "trial":
      return m.tenants_tenant_status_trial();
    case "suspended":
      return m.tenants_tenant_status_suspended();
    case "past_due":
      return m.tenants_tenant_status_past_due();
  }
}

export function StatusControl({
  tenant,
  onUpdated,
}: StatusControlProps): ReactElement {
  useLocale();
  const current = tenant.status;
  const isWorkspace = Boolean(tenant.parent_id);
  const targets = allowedTargets(current, isWorkspace);
  const [phase, setPhase] = useState<Phase>({ kind: "idle" });

  const applyStatus = useCallback(
    async (target: SettableTenantStatus, trialDays?: number): Promise<void> => {
      setPhase({ kind: "saving" });
      try {
        const updated = await updateTenantStatus(tenant.id, {
          target_status: target,
          ...(trialDays !== undefined ? { trial_days: trialDays } : {}),
        });
        onUpdated(updated);
        setPhase({ kind: "idle" });
      } catch (err: unknown) {
        setPhase({
          kind: "error",
          message: err instanceof Error ? err.message : "Status change failed",
        });
      }
    },
    [tenant.id, onUpdated],
  );

  const handleSelect = useCallback(
    (next: string) => {
      // Selecting the current value is a no-op — UX safety so the
      // dropdown doesn't fire a redundant write.
      if (next === current) return;
      const target = next as SettableTenantStatus;
      if (target === "trial") {
        // Defer to the trial-duration picker.
        setPhase({ kind: "picking_trial", days: 30 });
        return;
      }
      void applyStatus(target);
    },
    [current, applyStatus],
  );

  const cancelTrial = useCallback(() => {
    setPhase({ kind: "idle" });
  }, []);

  const confirmTrial = useCallback(() => {
    if (phase.kind !== "picking_trial") return;
    void applyStatus("trial", phase.days);
  }, [phase, applyStatus]);

  return (
    <div data-testid="status-control" className="flex flex-col gap-cog-2">
      <div className="flex items-center gap-cog-3">
        <TenantStatusPill
          status={tenant.status}
          trialDaysRemaining={tenant.trial_days_remaining}
        />
        <select
          value={current}
          onChange={(e) => handleSelect(e.target.value)}
          disabled={phase.kind === "saving" || phase.kind === "picking_trial"}
          aria-label={m.admin_workspaces_status_aria()}
          data-testid="status-control-select"
          className="
            rounded-base border border-cog-divider
            bg-cog-surface px-cog-2 py-cog-2
            text-body-sm text-cog-text-primary
            focus:border-cog-blue-600 focus:outline-none
            disabled:cursor-not-allowed disabled:opacity-50
          "
        >
          {/* When current is past_due, render it as a disabled-display
              option since the admin can never set it. */}
          {current === "past_due" && (
            <option value="past_due">{labelFor("past_due")} {m.workspaces_current_suffix()}</option>
          )}
          {targets.map((t) => (
            <option key={t} value={t}>
              {labelFor(t)}
              {t === current ? ` ${m.workspaces_current_suffix()}` : ""}
            </option>
          ))}
        </select>
        {phase.kind === "saving" && (
          <span className="text-body-sm text-cog-text-secondary">{m.workspaces_saving()}</span>
        )}
      </div>

      {phase.kind === "picking_trial" && (
        <div
          data-testid="status-control-trial-picker"
          className="flex flex-wrap items-center gap-cog-2 rounded-base border border-cog-divider bg-cog-surface-muted px-cog-3 py-cog-2"
        >
          <span className="text-body-sm font-semibold text-cog-text-primary">
            {m.workspaces_trial_length_label()}
          </span>
          {TRIAL_PRESETS.map((p) => {
            const selected = phase.days === p.days;
            return (
              <button
                key={p.days}
                type="button"
                onClick={() =>
                  setPhase({ kind: "picking_trial", days: p.days })
                }
                data-testid={`status-control-trial-preset-${p.days}`}
                className={[
                  "inline-flex h-cog-6 items-center rounded-base border px-cog-3 text-body-sm font-semibold",
                  "transition-colors duration-standard",
                  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1",
                  selected
                    ? "border-cog-blue-600 bg-cog-blue-50 text-cog-blue-700 dark:bg-cog-blue-950 dark:text-cog-blue-300"
                    : "border-cog-divider bg-cog-surface text-cog-text-primary hover:border-cog-border hover:bg-cog-surface-muted",
                ].join(" ")}
              >
                {p.label}
              </button>
            );
          })}
          <div className="ml-auto flex gap-cog-2">
            <button
              type="button"
              onClick={cancelTrial}
              data-testid="status-control-trial-cancel"
              className="
                inline-flex h-cog-6 items-center rounded-base border border-cog-divider
                bg-cog-surface px-cog-3 text-body-sm font-semibold text-cog-text-primary
                hover:border-cog-border hover:bg-cog-surface-muted
                focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1
              "
            >
              {m.workspaces_cancel_btn()}
            </button>
            <button
              type="button"
              onClick={confirmTrial}
              data-testid="status-control-trial-apply"
              className="
                inline-flex h-cog-6 items-center rounded-base
                border border-cog-blue-600 bg-cog-blue-600 px-cog-3
                text-body-sm font-semibold text-white
                hover:border-cog-blue-700 hover:bg-cog-blue-700
                focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1
                dark:border-cog-blue-700 dark:bg-cog-blue-700 dark:text-white
              "
            >
              {m.workspaces_apply_btn()}
            </button>
          </div>
        </div>
      )}

      {phase.kind === "error" && (
        <p
          role="alert"
          data-testid="status-control-error"
          className="rounded-base border border-cog-danger-200 bg-cog-danger-50 px-cog-3 py-cog-2 text-body-sm text-cog-danger-600 dark:border-cog-danger-800 dark:bg-cog-danger-950 dark:text-cog-danger-dark"
        >
          {phase.message}
        </p>
      )}
    </div>
  );
}


