/**
 * StudioAccessCard — C7 / story #928.
 *
 * Renders a settings card on the workspace detail page (Settings tab) that
 * lets org-admins and platform-admins disable/enable individual Studio tools
 * for the whole workspace.
 *
 * Design:
 *  - Card surface with heading + description paragraph.
 *  - <fieldset> / <legend> (a11y: role="group") containing 20 toggle-switch
 *    rows (shared ui Switch, role="switch"), grouped by the 5 Studio
 *    categories.
 *  - ON = enabled (positive polarity — supersedes the checked-=-blocked
 *    checkboxes specced in #928). The wire contract is unchanged: the
 *    deny-list inversion happens inside setToolEnabled only
 *    (switch ON ⇔ nodeType ∉ disabled_studio_tools).
 *  - Enter on a focused switch submits the form (Save) — keyboard parity
 *    with the checkbox era, where Enter triggered implicit submission;
 *    Space toggles, as before.
 *  - Save issues PATCH /api/v1/admin/tenants/:id with
 *    { disabled_studio_tools: nodeType[], clear_disabled_studio_tools: true }.
 *  - RBAC gate: tier prop "member" → hidden entirely. "org"/"platform" →
 *    rendered and interactive. No tier prop → rendered (unguarded usage).
 *
 * The 20 (nodeType, taskKey) pairs mirror STUDIO_TASKS_CONFIG in studio-mfe.
 * They are defined as a typed const here so admin-mfe has no MF dependency
 * on studio-mfe at build time.
 *
 * artboard: workspace-settings composition.
 */

import {
  type FormEvent,
  type KeyboardEvent,
  type ReactElement,
  useCallback,
  useEffect,
  useState,
} from "react";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { Switch } from "@omnicore-platform/ui";
import { updateTenant, type AdminTenant } from "../api/tenants";

// ─── Studio tool catalog (admin-mfe local copy of nodeType→taskKey) ──────────
//
// These 20 pairs are the stable identity of Studio tools in the org-flags wire
// contract. They do NOT reference studio-mfe imports (no MF dependency at
// build time). The nodeType is what the server stores in disabled_studio_tools.

type StudioCategory = "profiles" | "content" | "visual" | "media" | "analysis";

interface StudioToolDef {
  readonly nodeType: string;
  /** Paraglide task-name function — called at render time */
  readonly label: () => string;
  readonly category: StudioCategory;
}

// Explicit function-reference map avoids dynamic indexing (no `any`).
const STUDIO_TOOL_DEFS: readonly StudioToolDef[] = [
  // Profiles
  { nodeType: "audience_profile",   label: m.studio_task_audience_profile_name,   category: "profiles" },
  { nodeType: "brand_profile",      label: m.studio_task_brand_profile_name,      category: "profiles" },
  { nodeType: "voice_profile",      label: m.studio_task_voice_profile_name,      category: "profiles" },
  { nodeType: "character_generator",label: m.studio_task_character_studio_name,   category: "profiles" },
  // Content
  { nodeType: "research_assistant", label: m.studio_task_research_assistant_name, category: "content" },
  { nodeType: "content_planner",    label: m.studio_task_content_planner_name,    category: "content" },
  { nodeType: "content_studio",     label: m.studio_task_content_creator_name,    category: "content" },
  { nodeType: "test_content",       label: m.studio_task_content_testing_name,    category: "content" },
  { nodeType: "translation",        label: m.studio_task_translation_name,        category: "content" },
  { nodeType: "qr_code",            label: m.studio_task_qr_code_name,            category: "content" },
  // Visual
  { nodeType: "image_workspace",    label: m.studio_task_image_workspace_name,    category: "visual" },
  { nodeType: "image_suggestions",  label: m.studio_task_image_suggestions_name,  category: "visual" },
  { nodeType: "storyboard_creator", label: m.studio_task_storyboard_task_name,    category: "visual" },
  { nodeType: "design_canvas",      label: m.studio_task_design_canvas_name,      category: "visual" },
  // Media
  { nodeType: "text_to_speech",     label: m.studio_task_text_to_speech_name,     category: "media" },
  { nodeType: "audio_to_text",      label: m.studio_task_audio_to_text_name,      category: "media" },
  { nodeType: "video_to_text",      label: m.studio_task_video_to_text_name,      category: "media" },
  // Analysis
  { nodeType: "segmentation",       label: m.studio_task_segmentation_name,       category: "analysis" },
  { nodeType: "propaganda_analysis",label: m.studio_task_propaganda_analysis_name,category: "analysis" },
] as const;

const CATEGORY_ORDER: readonly StudioCategory[] = [
  "profiles", "content", "visual", "media", "analysis",
] as const;

// ─── Save state ───────────────────────────────────────────────────────────────

type SaveState =
  | { phase: "idle" }
  | { phase: "saving" }
  | { phase: "error"; message: string };

// ─── Props ────────────────────────────────────────────────────────────────────

export interface StudioAccessCardProps {
  readonly tenant: AdminTenant;
  readonly onUpdated: (next: AdminTenant) => void;
  /** Session tier. When "member" the card is not rendered. Omit to skip the
   *  gate (e.g. when the parent route already enforces RequireRole). */
  readonly tier?: "platform" | "org" | "member";
}

// ─── Component ────────────────────────────────────────────────────────────────

export function StudioAccessCard({
  tenant,
  onUpdated,
  tier,
}: StudioAccessCardProps): ReactElement | null {
  // RBAC gate — member tier never sees this card.
  if (tier === "member") return null;

  return <StudioAccessCardInner tenant={tenant} onUpdated={onUpdated} />;
}

// Inner component split so we can return null before hooks (Rules of Hooks).
function StudioAccessCardInner({
  tenant,
  onUpdated,
}: {
  readonly tenant: AdminTenant;
  readonly onUpdated: (next: AdminTenant) => void;
}): ReactElement {
  // Set of disabled nodeTypes — the controlled state driving the switches
  // (a switch renders ON when its nodeType is NOT in this set).
  const [disabled, setDisabled] = useState<ReadonlySet<string>>(
    () => new Set(tenant.disabled_studio_tools ?? []),
  );
  // Offline mode toggle — controlled boolean.
  const [offlineMode, setOfflineMode] = useState<boolean>(
    () => tenant.offline_mode ?? false,
  );
  const [save, setSave] = useState<SaveState>({ phase: "idle" });

  // Sync when tenant prop changes (e.g. after a reload from the parent).
  useEffect(() => {
    setDisabled(new Set(tenant.disabled_studio_tools ?? []));
    setOfflineMode(tenant.offline_mode ?? false);
    setSave({ phase: "idle" });
  }, [tenant.id, tenant.disabled_studio_tools, tenant.offline_mode]);

  // The ONLY place the positive-polarity UI meets the deny-list model:
  // enabled=true removes the tool from the disabled set, enabled=false adds
  // it. Call sites pass the switch state straight through — no negation.
  const setToolEnabled = useCallback((nodeType: string, enabled: boolean): void => {
    setDisabled((prev) => {
      const next = new Set(prev);
      if (enabled) {
        next.delete(nodeType);
      } else {
        next.add(nodeType);
      }
      return next;
    });
  }, []);

  // Keyboard parity with the checkbox era: Enter on a focused switch submits
  // the form (Save) instead of toggling the tool — a Radix Switch is a
  // <button>, whose native Enter activation would otherwise silently flip
  // the deny-list entry. Space keeps toggling (default button activation on
  // keyup is untouched).
  const submitOnEnter = useCallback(
    (e: KeyboardEvent<HTMLButtonElement>): void => {
      if (e.key === "Enter") {
        e.preventDefault();
        e.currentTarget.form?.requestSubmit();
      }
    },
    [],
  );

  const handleSave = useCallback(
    async (e: FormEvent<HTMLFormElement>): Promise<void> => {
      e.preventDefault();
      if (save.phase === "saving") return;
      setSave({ phase: "saving" });
      try {
        const updated = await updateTenant(tenant.id, {
          disabled_studio_tools: Array.from(disabled),
          clear_disabled_studio_tools: true,
          offline_mode: offlineMode,
        });
        onUpdated(updated);
        setSave({ phase: "idle" });
      } catch (err: unknown) {
        setSave({
          phase: "error",
          message: m.admin_studio_access_save_error(),
        });
        // Log the underlying error so it reaches observability, but don't
        // surface raw server messages — use the localized string only.
        if (typeof console !== "undefined") {
          console.error("[StudioAccessCard] save failed:", err);
        }
      }
    },
    [disabled, offlineMode, save.phase, tenant.id, onUpdated],
  );

  const disabledCount = disabled.size;

  return (
    <section
      data-testid="studio-access-card"
      className="flex flex-col gap-cog-4 rounded-xl border border-cog-divider bg-cog-surface p-cog-5"
    >
      {/* ── Card header ─────────────────────────────────────────────────── */}
      <div className="flex flex-col gap-cog-1">
        <h3 className="text-heading-sm text-cog-text-primary">
          {m.admin_studio_access_card_title()}
        </h3>
        <p className="text-body-sm text-cog-text-secondary">
          {m.admin_studio_access_card_description()}
        </p>
        {disabledCount > 0 && (
          <p className="text-body-sm font-medium text-cog-text-secondary">
            {m.admin_studio_access_tools_disabled_hint({ count: disabledCount })}
          </p>
        )}
      </div>

      {/* ── Form ────────────────────────────────────────────────────────── */}
      <form onSubmit={handleSave} className="flex flex-col gap-cog-4">

        {/* ── Offline mode toggle ─────────────────────────────────────── */}
        <div className="flex flex-col gap-cog-1 rounded-md border border-cog-divider p-cog-3">
          <label
            htmlFor="studio-offline-mode"
            className={[
              "flex cursor-pointer items-center gap-cog-3",
              "rounded-md px-cog-2 py-cog-1 transition-colors",
              "hover:bg-cog-surface-muted",
              "focus-within:ring-2 focus-within:ring-cog-focus focus-within:ring-offset-1",
              "min-h-tap",
            ].join(" ")}
          >
            <Switch
              id="studio-offline-mode"
              checked={offlineMode}
              onCheckedChange={(on) => setOfflineMode(on)}
              onKeyDown={submitOnEnter}
              aria-label={m.admin_studio_offline_toggle_label()}
              aria-describedby="studio-offline-mode-hint"
            />
            <span className="text-body-sm font-medium text-cog-text-primary">
              {m.admin_studio_offline_toggle_label()}
            </span>
          </label>
          <p
            id="studio-offline-mode-hint"
            className="ms-cog-3 ps-cog-4 text-body-xs text-cog-text-secondary"
          >
            {m.admin_studio_offline_toggle_hint()}
          </p>
        </div>

        <fieldset className="flex flex-col gap-cog-4 border-0 p-cog-0">
          <legend className="sr-only">{m.admin_studio_access_fieldset_legend()}</legend>

          {/* Render tool switches grouped by category */}
          {CATEGORY_ORDER.map((cat) => {
            const tools = STUDIO_TOOL_DEFS.filter((t) => t.category === cat);
            return (
              <div key={cat} className="flex flex-col gap-cog-2">
                <p className="text-eyebrow text-cog-text-eyebrow uppercase tracking-wider">
                  {categoryLabel(cat)}
                </p>
                {tools.map((tool) => {
                  const id = `studio-access-${tool.nodeType}`;
                  const isDisabled = disabled.has(tool.nodeType);
                  return (
                    <label
                      key={tool.nodeType}
                      htmlFor={id}
                      className={[
                        "flex cursor-pointer items-center gap-cog-3",
                        "rounded-md px-cog-2 py-cog-1 transition-colors",
                        "hover:bg-cog-surface-muted",
                        "focus-within:ring-2 focus-within:ring-cog-focus focus-within:ring-offset-1",
                        "min-h-tap",
                      ].join(" ")}
                    >
                      <Switch
                        id={id}
                        checked={!isDisabled}
                        onCheckedChange={(on) => setToolEnabled(tool.nodeType, on)}
                        onKeyDown={submitOnEnter}
                        aria-label={tool.label()}
                      />
                      <span className="text-body-sm text-cog-text-primary">
                        {tool.label()}
                      </span>
                    </label>
                  );
                })}
              </div>
            );
          })}
        </fieldset>

        {/* ── Error ──────────────────────────────────────────────────────── */}
        {save.phase === "error" && (
          <p
            role="alert"
            data-testid="studio-access-save-error"
            className="rounded-base border border-cog-danger-200 bg-cog-danger-50 px-cog-3 py-cog-2 text-body-sm text-cog-danger-600 dark:border-cog-danger-800 dark:bg-cog-danger-950 dark:text-cog-danger-dark"
          >
            {save.message}
          </p>
        )}

        {/* ── Save button ─────────────────────────────────────────────────── */}
        <div>
          <button
            type="submit"
            disabled={save.phase === "saving"}
            data-testid="studio-access-save"
            className="
              inline-flex h-cog-6-5 items-center rounded-base
              border border-cog-blue-600 bg-cog-blue-600 px-cog-3
              text-body-sm font-semibold text-white
              transition-colors duration-standard
              hover:border-cog-blue-700 hover:bg-cog-blue-700
              focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1
              disabled:cursor-not-allowed disabled:border-cog-divider disabled:bg-cog-surface-muted disabled:text-cog-text-tertiary
              dark:border-cog-blue-700 dark:bg-cog-blue-700 dark:text-white
            "
          >
            {save.phase === "saving"
              ? m.admin_studio_access_saving()
              : m.admin_studio_access_save_btn()}
          </button>
        </div>
      </form>
    </section>
  );
}

// ─── Category label helper ─────────────────────────────────────────────────────
//
// Mirrors the one in studio-mfe/src/config/studioTasks.ts but stays local to
// admin-mfe so there is no cross-MFE build dependency.

function categoryLabel(cat: StudioCategory): string {
  switch (cat) {
    case "profiles":  return m.studio_category_profiles_name();
    case "content":   return m.studio_category_content_name();
    case "visual":    return m.studio_category_visual_name();
    case "media":     return m.studio_category_media_name();
    case "analysis":  return m.studio_category_analysis_name();
  }
}


